'use strict';
const marketingState={view:'campaigns',archived:false,segmentId:'',campaignId:'',query:'',memberStatus:'all',payload:null,preview:null};
const marketingButton=(label,action,style='')=>button(label,'x-marketing-'+action,style).replace('<button ','<button type="button" ');
const preMarketingTabs=crmTabs;crmTabs=function(){return preMarketingTabs().replace('</div>',`<button class="btn ${crmState.tab==='marketing'?'primary':''}" data-action="x-marketing-open" aria-pressed="${crmState.tab==='marketing'}">Segmentos y campañas</button></div>`);};
const marketingChannels={phone:'Llamada',whatsapp:'WhatsApp',email:'Correo'};
const consentLabels={yes:'Autorización registrada',no:'No contactar',unknown:'Sin registrar'};
function marketingNav(){return `<div class="row marketing-nav">${marketingButton('Campañas','campaigns',['campaigns','campaign'].includes(marketingState.view)?'primary':'')}${marketingButton('Segmentos','segments',['segments','segment'].includes(marketingState.view)?'primary':'')}<small>Seguimiento manual · sin envíos automáticos</small></div>`;}
function segmentSummary(f){const parts=[f.active==='active'?'Clientes activos':f.active==='inactive'?'Clientes inactivos':'Todos los estados'];if(f.tag)parts.push('Etiqueta: '+f.tag);if(f.buyer!=='any')parts.push(({never:'Sin compras reconocidas',repeat:'Dos o más compras reconocidas',with:'Con compras reconocidas'})[f.buyer]);if(f.category)parts.push('Categoría: '+f.category);if(f.metal)parts.push('Metal: '+f.metal);if(f.minSpent!==null)parts.push('Compras netas desde '+money(f.minSpent));if(f.inactiveDays!==null)parts.push('Sin comprar por '+f.inactiveDays+' días');if(f.debt!=='any')parts.push(({owing:'Con saldo',overdue:'Con saldo vencido',clear:'Sin saldo'})[f.debt]);if(f.openQuote!=='any')parts.push(f.openQuote==='yes'?'Con cotización vigente':'Sin cotización vigente');if(f.consent!=='any')parts.push(consentLabels[f.consent]);if(f.channel!=='any')parts.push('Canal: '+(marketingChannels[f.channel]||'Sin registrar'));if(f.birthdayMonth!==null)parts.push('Cumpleaños en el mes '+f.birthdayMonth);return parts.join(' · ');}
function segmentList(r){return `<section class="card"><div class="card-head"><div><h2>Grupos que se mantienen al día.</h2><small>Guardamos criterios y consultamos los clientes actuales. Cada usuario ve su ámbito autorizado.</small></div><div class="row">${r.manager&&allowed('crm','crear')?marketingButton('Nuevo segmento','segment-new','primary'):''}${r.manager?marketingButton(marketingState.archived?'Ver activos':'Ver archivados','segment-archived','text'):''}</div></div>${r.manager&&allowed('crm','crear')?`<div class="marketing-presets"><small>Empieza con una base:</small>${allowed('ventas')?marketingButton('Clientes recurrentes','preset-repeat','text')+marketingButton('Sin compra en 90 días','preset-inactive','text'):''}${marketingButton('Cotizaciones vigentes','preset-quotes','text')}</div>`:''}<div class="marketing-grid">${r.segments.length?r.segments.map(s=>`<article class="crm-deal"><div class="row between"><h3>${esc(s.name)}</h3>${s.archivedAt?badge('Archivado'):badge(s.count+' clientes')}</div><p>${esc(s.description||segmentSummary(s.filters))}</p><small>${esc(segmentSummary(s.filters))}</small><div class="row">${marketingButton('Ver clientes','segment-'+s.id,'text')}${r.manager&&allowed('crm','editar')?marketingButton(s.archivedAt?'Restaurar':'Editar',s.archivedAt?'segment-restore-'+s.id:'segment-edit-'+s.id,'text'):''}${!s.archivedAt&&r.manager&&allowed('crm','eliminar')?marketingButton('Archivar','segment-archive-'+s.id,'text'):''}</div></article>`).join(''):empty('Define a quién quieres acompañar.','Crea un segmento por intereses, compras, etiquetas o cotizaciones pendientes.')}</div></section>${crmPager(r.segmentTotal)}`;}
function segmentView(r){const s=r.segment,p=s.preview;return `<div class="row between crm-spacing">${marketingButton('Volver a segmentos','segments','text')}${r.manager&&!s.archivedAt&&allowed('crm','crear')?marketingButton('Preparar campaña','campaign-for-'+s.id,'primary'):''}</div><section class="card"><div class="card-head"><div><h2>${esc(s.name)}</h2><small>${esc(segmentSummary(s.filters))}</small></div>${badge(p.total+' clientes')}</div>${p.items.length?table(['Cliente','Contacto actual','Autorización'],p.items.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.doc||'Sin documento')}</small></td><td>${esc(c.phone||'Sin teléfono')}<small>${esc(c.email||'')}</small></td><td>${esc(consentLabels[c.consent])}</td></tr>`)):empty('El segmento aún no tiene coincidencias.','Se actualizará cuando cambien los datos reales de tus clientes.')}</section>${crmPager(p.total)}<p class="muted commercial-hint">Pertenecer a un segmento no autoriza contacto comercial. La campaña verifica autorización, canal y criterios de nuevo.</p>`;}
function campaignList(r){return `<section class="card"><div class="card-head"><div><h2>Conversaciones con intención.</h2><small>Planifica, revisa la audiencia y registra el seguimiento que tu equipo realiza.</small></div>${r.manager&&allowed('crm','crear')?marketingButton('Nueva campaña','campaign-new','primary'):''}</div><div class="marketing-grid">${r.campaigns.length?r.campaigns.map(c=>`<article class="crm-deal"><div class="row between"><h3>${esc(c.name)}</h3>${badge(r.statuses[c.status])}</div><p>${esc(c.objective)}</p><small>${esc(c.segmentName||'')} · ${esc(marketingChannels[c.channel])}</small><small>${crmDate(c.startDate)} — ${crmDate(c.endDate)}</small><div class="marketing-card-metrics"><span><strong>${c.audience}</strong> clientes</span><span><strong>${c.contacted}</strong> con registro</span><span><strong>${c.opportunities}</strong> oportunidades</span></div>${marketingButton('Abrir campaña','campaign-'+c.id,'text')}</article>`).join(''):empty('Una buena campaña empieza con un grupo claro.','Crea un segmento y prepara tu primera campaña. Nada se enviará automáticamente.',marketingButton('Ver segmentos','segments','primary'))}</div></section>${crmPager(r.campaignTotal)}`;}
function campaignView(r){const c=r.campaign,a=c.stats,canManage=r.manager&&allowed('crm','editar'),inWindow=appState.today>=c.startDate&&appState.today<=c.endDate,canContact=c.status==='active'&&inWindow;return `<div class="row between crm-spacing">${marketingButton('Volver a campañas','campaigns','text')}<span class="crm-beta">${esc(r.statuses[c.status])}</span></div><section class="card"><div class="card-head"><div><h2>${esc(c.name)}</h2><small>${esc(c.segmentName||(r.segmentOptions.find(s=>s.id===c.segmentId)?.name)||'')} · ${esc(marketingChannels[c.channel])} · ${crmDate(c.startDate)} — ${crmDate(c.endDate)}</small></div><div class="row">${c.status==='draft'&&canManage?marketingButton('Editar borrador','campaign-edit','text')+marketingButton('Revisar audiencia e iniciar','audience','primary'):''}${['active','paused'].includes(c.status)&&canManage?marketingButton('Actualizar audiencia','audience')+marketingButton(c.status==='active'?'Pausar':'Reanudar',c.status==='active'?'pause':'resume')+marketingButton('Finalizar','finish','text'):''}</div></div><div class="card-body"><p>${esc(c.objective)}</p>${c.script?`<details class="marketing-script"><summary>Guion interno de la campaña</summary><p class="crm-text">${esc(c.script)}</p></details>`:''}${c.budget!==undefined?`<p class="muted commercial-hint">Presupuesto previsto: ${money(c.budget)}. Es planificación; no registra gastos ni calcula rentabilidad.</p>`:''}<p class="muted commercial-hint">${c.status==='draft'?'Revisa la audiencia antes de iniciar.':!inWindow?'La campaña está fuera de su periodo de seguimiento.':'La audiencia conserva los criterios del inicio. Actualízala para incorporar nuevas coincidencias.'} Los datos y las autorizaciones se comprueban al registrar cada contacto.</p></div></section><div class="kpis crm-kpis crm-spacing">${kpi('Clientes en campaña',a.audience,a.eligible+' elegibles por perfil',true)+kpi('Clientes con registro',a.contacted,'Interacciones registradas manualmente')+kpi('Oportunidades',a.opportunities,'Vinculadas explícitamente')+kpi('Ventas vinculadas',a.sales===undefined?'—':a.sales,a.revenue===undefined?'Según permisos':money(a.revenue)+' netos reconocidos')}</div><section class="card crm-spacing"><div class="card-head"><div><h2>Seguimiento de clientes</h2><small>Registra interacciones manuales o prepara mensajes individuales. Las entregas se consultan en Comunicaciones.</small></div></div><form id="marketing-members-filter" class="crm-search"><label class="search">${icon('search')}<input name="query" aria-label="Buscar clientes de campaña" placeholder="Nombre, documento o contacto" value="${esc(marketingState.query)}"></label>${select('Mostrar','memberStatus',[['all','Todos'],['blocked','No elegibles'],['pending','Pendientes'],...Object.entries(r.outcomes)],marketingState.memberStatus)}${submit('Consultar')}</form>${c.members.length?table(['Cliente / responsable','Canal de referencia','Resultado',''],c.members.map(m=>{const rejected=['not_interested','opted_out'].includes(m.status),activeOpp=m.opportunities.some(o=>!['won','lost'].includes(o.stage));return `<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.doc||'Sin documento')}</small><small>${esc(r.members.find(u=>u.id===m.ownerId)?.name||(m.ownerId?'Cliente asignado':'Sin asignar'))}</small></td><td>${esc(c.channel==='email'?m.email:m.phone)}<small>${esc(consentLabels[m.consent])}</small></td><td>${esc(r.outcomes[m.status]||'Pendiente')}${m.blocked?`<small class="marketing-blocked">${esc(m.blocked)}</small>`:''}${m.opportunities.map(o=>`<small>${esc(o.number)} · ${esc(({new:'Nuevo interés',contacted:'Contactado',appointment:'Asesoría',quoted:'Cotización',decision:'En decisión',won:'Ganada',lost:'Perdida'})[o.stage])}</small>`).join('')}</td><td><details class="marketing-actions" name="marketing-recipient-actions"><summary class="btn">Acciones</summary><div>${marketingButton('Historial','member-history-'+m.customerId,'text')}${m.opportunities.map(o=>commercialButton('Abrir '+o.number,'open-'+o.id,'text')).join('')}${allowed('crm','crear')&&canContact&&!m.blocked&&!rejected?marketingButton('Registrar contacto','contact-'+m.customerId,'text')+(!activeOpp?marketingButton('Crear oportunidad','opportunity-'+m.customerId,'text'):''):''}${allowed('crm','crear')&&m.consent!=='no'?marketingButton('Registrar baja','optout-'+m.customerId,'text'):''}</div></details></td></tr>`; })):empty(c.status==='draft'?'La audiencia se incorporará al iniciar.':'No hay clientes en esta vista.','Revisa los filtros y la audiencia de la campaña.')}</section>${crmPager(c.total)}<p class="muted commercial-hint">Las ventas provienen únicamente de oportunidades vinculadas y ventas reconocidas en el POS. Se excluyen anulaciones y separes aún sin entregar; pueden cerrarse después del periodo de la campaña.</p>${c.history?.length?`<section class="card card-body crm-spacing"><h2>Historial de la campaña</h2>${c.history.slice().reverse().map(e=>`<article class="crm-entry"><p>${esc(r.statuses[e.status])} · ${esc(e.reason)}</p><small>${esc(e.author)} · ${crmDate(e.createdAt)}</small></article>`).join('')}</section>`:''}`;}
const loadBeforeMarketing=loadCrm;loadCrm=async function(){if(crmState.tab!=='marketing')return loadBeforeMarketing();const target=document.querySelector('#crm-content');if(!target)return;try{const q={page:crmState.page,archived:marketingState.archived?'1':'0',memberStatus:marketingState.memberStatus,query:marketingState.query,...(marketingState.view==='segment'?{segmentId:marketingState.segmentId}:{}),...(marketingState.view==='campaign'?{campaignId:marketingState.campaignId}:{})},r=await api('/api/crm/marketing?'+new URLSearchParams(q));if(!target.isConnected)return;marketingState.payload=r;target.innerHTML=marketingNav()+(marketingState.view==='segments'?segmentList(r):marketingState.view==='segment'?segmentView(r):marketingState.view==='campaign'?campaignView(r):campaignList(r));}catch(e){if(target.isConnected)target.innerHTML=marketingNav()+empty('No pudimos consultar segmentos y campañas.',e.message,marketingButton('Reintentar','retry'));}};
function marketingSegmentForm(id,preset={}){const r=marketingState.payload,s=id?r.segments.find(s=>s.id===id)||r.segment:null,f=s?.filters||{active:'active',buyer:'any',debt:'any',consent:'any',channel:'any',openQuote:'any',tag:'',category:'',metal:'',ownerId:'',minSpent:null,inactiveDays:null,birthdayMonth:null,...preset};modal(s?'Editar segmento':'Nuevo segmento dinámico',pForm('marketing-segment-form',input('Nombre del segmento','name',s?.name||preset.name||'','text','required maxlength="100"')+input('Descripción (opcional)','description',s?.description||'','text','maxlength="500"')+`<div class="form-grid">${select('Estado de los clientes','active',[['active','Activos'],['inactive','Inactivos'],['all','Todos']],f.active)+input('Etiqueta exacta (opcional)','tag',f.tag,'text','maxlength="40"')+select('Responsable','ownerId',[['','Cualquier responsable'],...r.members.map(m=>[m.id,m.name])],f.ownerId)+select('Canal preferido','channel',[['any','Cualquiera'],['phone','Llamada'],['whatsapp','WhatsApp'],['email','Correo'],['unknown','Sin registrar']],f.channel)+select('Autorización comercial','consent',[['any','Cualquiera'],['yes','Registrada'],['no','No contactar'],['unknown','Sin registrar']],f.consent)+select('Cotización emitida y vigente','openQuote',[['any','Cualquiera'],['yes','Con cotización'],['no','Sin cotización']],f.openQuote)}</div><details class="marketing-advanced"><summary>Compras, cartera y fechas</summary><div class="form-grid">${select('Historial de compras reconocidas','buyer',[['any','Cualquiera'],['never','Sin compras reconocidas'],['with','Con compras'],['repeat','Dos o más compras']],f.buyer)+input('Compras netas mínimas COP','minSpent',f.minSpent??'','number','min="0" max="1000000000000" step="1"')+input('Sin comprar durante al menos (días)','inactiveDays',f.inactiveDays??'','number','min="0" max="3650" step="1"')+select('Categoría actual de productos comprados','category',[['','Cualquiera'],...new Set([...r.categories,...(f.category?[f.category]:[])])],f.category)+select('Metal de las piezas compradas','metal',[['','Cualquiera'],...new Set([...r.metals,...(f.metal?[f.metal]:[])])],f.metal)+select('Saldo del cliente','debt',[['any','Cualquiera'],['owing','Con saldo'],['overdue','Con saldo vencido'],['clear','Sin saldo']],f.debt)+select('Mes de cumpleaños','birthdayMonth',[['','Cualquiera'],...['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'].map((m,i)=>[String(i+1),m])],f.birthdayMonth??'')}</div><p class="muted">Sin compra en N días exige una compra reconocida previa. Los históricos archivados de Charles no se incluyen.</p></details><div id="marketing-segment-preview"></div>${marketingButton('Vista previa de coincidencias','segment-preview','text')}`,'Guardar segmento',`data-id="${esc(s?.id||'')}"`));}
function formSegment(form){const v=Object.fromEntries(new FormData(form));return {name:v.name,description:v.description,filters:Object.fromEntries(['active','tag','ownerId','channel','consent','openQuote','buyer','minSpent','inactiveDays','category','metal','debt','birthdayMonth'].map(k=>[k,v[k]]))};}
function marketingCampaignForm(edit=false,segmentId=''){const r=marketingState.payload,c=edit?r.campaign:null,options=r.segmentOptions;if(!options.length){toast('Crea primero un segmento activo para preparar la campaña.');return;}const end=new Date(appState.today+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+14);modal(c?'Editar borrador de campaña':'Preparar campaña',pForm('marketing-campaign-form',input('Nombre de la campaña','name',c?.name||'','text','required maxlength="120"')+input('Objetivo','objective',c?.objective||'','text','required maxlength="500"')+select('Segmento dinámico','segmentId',options.map(s=>[s.id,s.name]),c?.segmentId||segmentId)+select('Canal de seguimiento manual','channel',[['phone','Llamada'],['whatsapp','WhatsApp'],['email','Correo']],c?.channel||'phone')+`<div class="form-grid">${input('Inicio del seguimiento','startDate',c?.startDate||appState.today,'date','required')+input('Fin del seguimiento','endDate',c?.endDate||end.toISOString().slice(0,10),'date','required')}</div>`+input('Presupuesto previsto COP (no registra gasto)','budget',c?.budget||0,'number','min="0" step="1" required')+`<label class="field"><span>Guion o propuesta de uso interno</span><textarea name="script" rows="4" maxlength="2000">${esc(c?.script||'')}</textarea></label><p class="muted">Se guardará un borrador. Antes de iniciar revisarás quiénes son elegibles. Guardar la campaña no envía mensajes. Los envíos individuales se preparan y revisan en Comunicaciones.</p>`,'Guardar borrador',`data-id="${esc(c?.id||'')}"`));}
function showCampaignAudience(p){marketingState.preview=p;const c=marketingState.payload.campaign;modal('Revisar audiencia de campaña',pForm('marketing-audience-form',`<div class="marketing-preview-counts"><span><strong>${p.matched}</strong> coinciden</span><span><strong>${p.eligible}</strong> elegibles</span><span><strong>${p.total}</strong> incorporaciones nuevas</span></div>${Object.entries(p.excluded).map(([reason,count])=>`<p class="marketing-blocked">${count} · ${esc(reason)}</p>`).join('')}${p.blocked?'<p class="marketing-blocked">Hay más de 500 incorporaciones. Reduce el segmento.</p>':''}${p.items.length?table(['Cliente','Revisión'],p.items.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.reason)}${m.existing?' · Ya incorporado':''}</td></tr>`)):''}<p class="muted">Muestra de hasta 30 clientes. Iniciar o actualizar solo prepara el seguimiento interno. No se envían mensajes.</p>`,c.status==='draft'?'Iniciar seguimiento interno':'Incorporar nuevos clientes',`data-id="${esc(c.id)}" data-command="${c.status==='draft'?'crm.campaign.launch':'crm.campaign.refresh'}"`));if(p.blocked||!p.total)document.querySelector('#marketing-audience-form button[type=submit]').disabled=true;}
function campaignMember(id){return marketingState.payload.campaign.members.find(m=>m.customerId===id);}
function campaignContactForm(id,optout=false){const r=marketingState.payload,c=r.campaign,m=campaignMember(id);modal(optout?'Registrar solicitud de baja':'Registrar interacción realizada',pForm('marketing-contact-form',`<p>${esc(m.name)} · ${esc(marketingChannels[c.channel])}</p>${select('Resultado','outcome',optout?[['opted_out','Solicita no contactar']]:Object.entries(r.outcomes),'contacted')}${input('Fecha real de la interacción','contactDate',appState.today,'date','required')}<label class="field"><span>Resultado o contexto</span><textarea name="note" rows="4" maxlength="1000" required></textarea></label><p class="muted">Es un registro manual. Elegir una baja marca al cliente como no autorizado para contacto comercial y se aplica a todas las campañas.</p>`,'Guardar interacción',`data-customer="${esc(id)}" data-campaign="${esc(c.id)}"`));}
function campaignOpportunityForm(id){const c=marketingState.payload.campaign,m=campaignMember(id);modal('Crear oportunidad desde campaña',pForm('marketing-opportunity-form',`<p>${esc(m.name)} · ${esc(c.name)}</p>${input('Interés del cliente','title','','text','required maxlength="160"')+input('Valor estimado COP','amount',0,'number','required min="0" step="1"')+input('Próxima acción','nextAction','','text','required maxlength="180"')+input('Fecha de próxima acción','nextDate',appState.today,'date','required')}<label class="field"><span>Contexto</span><textarea name="description" rows="3" maxlength="1000"></textarea></label><p class="muted">La oportunidad conservará el vínculo con esta campaña. Las cotizaciones y ventas se gestionan desde Oportunidades y el POS.</p>`,'Crear oportunidad vinculada',`data-customer="${esc(id)}" data-campaign="${esc(c.id)}"`));}
const beforeMarketingAction=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-marketing-'))return beforeMarketingAction(a,t);const action=a.slice(12);if(['open','campaigns','segments'].includes(action)){closeModal();crmState.tab='marketing';crmState.page=0;if(action!=='open')marketingState.view=action;render();return;}if(action==='retry')return loadCrm();if(action==='segment-archived'){marketingState.archived=!marketingState.archived;crmState.page=0;render();return;}if(action==='segment-new')return marketingSegmentForm();if(action.startsWith('preset-')){const preset={repeat:{name:'Clientes recurrentes',buyer:'repeat'},inactive:{name:'Sin compra en 90 días',inactiveDays:90},quotes:{name:'Cotizaciones vigentes',openQuote:'yes'}}[action.slice(7)];return marketingSegmentForm('',preset);}if(action.startsWith('segment-edit-'))return marketingSegmentForm(action.slice(13));if(action.startsWith('segment-archive-')||action.startsWith('segment-restore-')){const restore=action.startsWith('segment-restore-'),id=action.slice(restore?16:16);return modal(restore?'Restaurar segmento':'Archivar segmento',pForm('marketing-segment-state-form',`<p>${restore?'El segmento volverá a estar disponible.':'El segmento se conservará en Archivados. Las campañas iniciadas mantienen sus criterios originales.'}</p>`,restore?'Restaurar':'Archivar',`data-id="${esc(id)}" data-command="${restore?'crm.segment.restore':'crm.segment.archive'}"`));}if(action==='segment-preview'){const form=document.querySelector('#marketing-segment-form'),target=document.querySelector('#marketing-segment-preview'),data=formSegment(form),r=await api('/api/crm/marketing/segment-preview',{method:'POST',body:JSON.stringify({filters:data.filters})});if(!target.isConnected)return;target.innerHTML=`<section class="card card-body crm-spacing"><h3>${r.total} clientes coinciden</h3><p class="muted">Muestra de hasta 25 clientes. Vista previa, todavía sin guardar.</p>${r.items.map(c=>`<p>${esc(c.name)} · ${esc(c.doc||'Sin documento')}</p>`).join('')}</section>`;return;}if(action.startsWith('segment-')){marketingState.segmentId=action.slice(8);marketingState.view='segment';crmState.page=0;render();return;}if(action==='campaign-new')return marketingCampaignForm();if(action==='campaign-edit')return marketingCampaignForm(true);if(action.startsWith('campaign-for-'))return marketingCampaignForm(false,action.slice(13));if(action.startsWith('campaign-')){crmState.tab='marketing';marketingState.campaignId=action.slice(9);marketingState.view='campaign';crmState.page=0;marketingState.query='';marketingState.memberStatus='all';render();return;}if(action==='audience'){const c=marketingState.payload.campaign,p=await api('/api/crm/marketing/campaign-preview',{method:'POST',body:JSON.stringify({campaignId:c.id})});return showCampaignAudience(p);}if(['pause','resume','finish'].includes(action)){const status={pause:'paused',resume:'active',finish:'completed'}[action],c=marketingState.payload.campaign;return modal(action==='finish'?'Finalizar campaña':action==='pause'?'Pausar campaña':'Reanudar campaña',pForm('marketing-status-form','<label class="field"><span>Motivo</span><textarea name="reason" rows="3" maxlength="500" required></textarea></label>','Guardar estado',`data-id="${esc(c.id)}" data-status="${status}"`));}if(action.startsWith('member-history-')){const m=campaignMember(action.slice(15)),r=marketingState.payload;return modal('Historial · '+m.name,m.attempts.length?m.attempts.map(e=>`<article class="crm-entry"><p><strong>${esc(r.outcomes[e.outcome])}</strong> · ${esc(e.note)}</p><small>${crmDate(e.contactDate)} · ${esc(e.author)} · Registro manual</small></article>`).join(''):'<p class="muted">Todavía no hay interacciones registradas para este cliente en la campaña.</p>');}if(action.startsWith('contact-'))return campaignContactForm(action.slice(8));if(action.startsWith('optout-'))return campaignContactForm(action.slice(7),true);if(action.startsWith('opportunity-'))return campaignOpportunityForm(action.slice(12));};
const beforeMarketingSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(form.id==='marketing-members-filter'){marketingState.query=v.query;marketingState.memberStatus=v.memberStatus;crmState.page=0;render();return null;}if(form.id==='marketing-segment-form')return {command:'crm.segment.save',body:{...formSegment(form),id:form.dataset.id||undefined}};if(form.id==='marketing-segment-state-form'){crmState.page=0;return {command:form.dataset.command,body:{id:form.dataset.id}};}if(form.id==='marketing-campaign-form')return {command:'crm.campaign.save',body:{...v,id:form.dataset.id||undefined}};if(form.id==='marketing-audience-form')return {command:form.dataset.command,body:{id:form.dataset.id,digest:marketingState.preview.digest}};if(form.id==='marketing-status-form')return {command:'crm.campaign.status',body:{id:form.dataset.id,status:form.dataset.status,reason:v.reason}};if(form.id==='marketing-contact-form')return {command:'crm.campaign.contact',body:{...v,customerId:form.dataset.customer,campaignId:form.dataset.campaign}};if(form.id==='marketing-opportunity-form')return {command:'crm.campaign.opportunity',body:{...v,customerId:form.dataset.customer,campaignId:form.dataset.campaign}};return beforeMarketingSubmit(form,v);};

const beforeMarketingMutation=mutate;mutate=async function(command,body,form){const result=await beforeMarketingMutation(command,body,form);if(appState.route==='crm'&&result.entityId){if(command==='crm.segment.save'){marketingState.segmentId=result.entityId;marketingState.view='segment';crmState.page=0;}if(command==='crm.campaign.save'){marketingState.campaignId=result.entityId;marketingState.view='campaign';crmState.page=0;}if(command==='crm.campaign.opportunity'){commercialState.opportunityId=result.entityId;crmState.tab='opportunity';crmState.page=0;}}return result;};

const campaignOpportunityView=opportunityView;opportunityView=function(r){const html=campaignOpportunityView(r),o=r.opportunity;if(!o.campaignId)return html;return '<div class="info-strip">Origen: '+esc(o.campaign?.name||'Campaña comercial')+(o.campaign?marketingButton('Ver campaña','campaign-'+o.campaign.id,'text'):'')+'</div>'+html;};
